-- ============================================================
-- PHAN 1: POSTGRESQL PGVECTOR 0.8.0+ (FORCE RLS + ITERATIVE SCAN)
-- ============================================================
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE rag_document_chunks (
  chunk_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      TEXT NOT NULL,
  agency_id      TEXT NOT NULL,
  source_sha256  CHAR(64) NOT NULL,
  trust_tier     TEXT NOT NULL CHECK (trust_tier IN ('INTERNAL_VERIFIED', 'EXTERNAL_SANITIZED')),
  effective_stat TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (effective_stat IN ('ACTIVE', 'ARCHIVED')),
  clean_content  TEXT NOT NULL,
  embedding      VECTOR(1536) NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_rag_chunks_hnsw ON rag_document_chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX idx_rag_chunks_tenant_active ON rag_document_chunks (tenant_id, agency_id, effective_stat);

ALTER TABLE rag_document_chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE rag_document_chunks FORCE ROW LEVEL SECURITY;

CREATE POLICY rag_tenant_isolation_policy ON rag_document_chunks
  USING (
    tenant_id = current_setting('app.current_tenant_id', true)
    AND agency_id = current_setting('app.current_agency_id', true)
    AND effective_stat = 'ACTIVE'
  );

-- Truy van an toan trong 1 transaction: chong ro ri chéo & chong Overfiltering
BEGIN;
  SET LOCAL app.current_tenant_id = 'tenant_ecolife';
  SET LOCAL app.current_agency_id = 'agency_f1_tunglong';
  SET LOCAL hnsw.iterative_scan = strict_order;
  SET LOCAL hnsw.max_scan_tuples = 20000;

  SELECT chunk_id, trust_tier, clean_content, 1 - (embedding <=> $1::vector) AS similarity
  FROM rag_document_chunks
  WHERE trust_tier = 'INTERNAL_VERIFIED'
  ORDER BY embedding <=> $1::vector
  LIMIT 6;
COMMIT;

